function normaliserCasse(texte: string): string {
  return texte
    .normalize("NFC")
    .replace(/[’‘‛]/g, "'")
    .replace(/[“”„]/g, '"')
    .replace(/[‐‑‒–—]/g, "-")
    .replace(/[\u00a0\s]+/g, " ")
    .trim();
}

function normaliser(texte: string): string {
  return normaliserCasse(texte).toLocaleLowerCase("fr");
}

// D'abord une recherche qui respecte la casse pour départager les libellés
// homographes (par ex. « lecture » = Play dans l'animation, « Lecture » =
// Read pour l'action d'un outil). Le repli insensible à la casse conserve la
// tolérance aux variations normales de capitalisation du reste de l'interface.
const INDEX_EN_EXACT = new Map(
  Object.entries(EN).map(([fr, en]) => [normaliserCasse(fr), en])
);
const INDEX_EN = new Map(Object.entries(EN).map(([fr, en]) => [normaliser(fr), en]));

export function traduireTexteInterface(texte: string, locale: Locale): string {
  if (locale !== "en") return texte;
  const cleExacte = normaliserCasse(texte);
  if (!cleExacte) return texte;
  const traductionExacte = INDEX_EN_EXACT.get(cleExacte);
  if (traductionExacte) return traductionExacte;
  const cle = normaliser(texte);
  const traduction = INDEX_EN.get(cle);
  if (traduction) return traduction;
  const dynamique = [
    [/^création\s+(\d+)\s*%$/i, "Creating $1%"],
    [/^étape\s+(\d+)$/i, "Step $1"],
    [/^page\s+(\d+)$/i, "Page $1"],
    [/^chargement de (.+)…$/i, "Loading $1…"],
    [/^chargement de (.+)\.\.\.$/i, "Loading $1..."],
    [/^texte collé,?\s+([\d\s\u00a0.,]+) caractères$/i, "Pasted text, $1 characters"],
    [/^code collé,?\s+(.+)$/i, "Pasted code, $1"],
    [/^formule collée,?\s+latex$/i, "Pasted formula, LaTeX"],
    [/^il y a (\d+) sem$/i, "$1 weeks ago"],
    [/^il y a (\d+) min(?:ute)?s?$/i, "$1 minutes ago"],
    [/^il y a (\d+) h(?:eure)?s?$/i, "$1 hours ago"],
    [/^créé il y a (\d+) jours?$/i, "Created $1 days ago"],
    [/^modifié il y a (\d+) jours?$/i, "Updated $1 days ago"],
    [/^reçu de (.+)$/i, "Received from $1"],
    [/^renvoyer le lien \((\d+)\s*s\)$/i, "Resend link ($1 s)"],
    [/^(.+) réfléchit…$/i, "$1 is thinking…"],
    [/^(.+) réfléchit\.\.\.$/i, "$1 is thinking..."],
    [/^(.+) réfléchit$/i, "$1 is thinking"],
  ] as const;
  const texteDynamique = normaliserCasse(texte);
  for (const [motif, remplacement] of dynamique) {
    if (motif.test(texteDynamique)) return texteDynamique.replace(motif, remplacement);
  }
  return texte;
}
